<script setup>
import {Head,Link,useForm,router,usePoll} from '@inertiajs/vue3';
import {computed} from 'vue';
import AdminLayout from '../../Components/AdminLayout.vue';
import Pagination from '../../Components/Pagination.vue';
import {states} from '../../labels';
const props=defineProps({batch:Object,batches:Object,segments:Array,branches:Array});
const form=useForm({file:null,type:'catalog',segment_id:'',branch_id:''});
const branches=computed(()=>props.branches.filter(b=>!form.segment_id||b.segments?.some(s=>s.id===form.segment_id)));
const confirmation=useForm({});
usePoll(4000,{only:['batch','batches']},{autoStart:true});
function submit(){form.transform(d=>({...d,branch_id:d.type==='inventory'?d.branch_id:null})).post('/admin/importacoes',{forceFormData:true});}
</script>
<template><AdminLayout><Head title="Importações"/><div class="page-heading"><div><span class="eyebrow">Catálogo e inventário</span><h1>Importações</h1><p>Envie o ficheiro, reveja cada linha e confirme o processamento.</p></div></div><form class="panel admin-form" @submit.prevent="submit"><div class="form-grid"><div class="field"><label for="import-type">Tipo</label><select id="import-type" v-model="form.type"><option value="catalog">Produtos</option><option value="inventory">Contagem de stock</option></select></div><div class="field"><label for="import-segment">Segmento</label><select id="import-segment" v-model="form.segment_id" required @change="form.branch_id=''"><option value="">Selecionar…</option><option v-for="s in segments" :key="s.id" :value="s.id">{{s.name}}</option></select></div><div v-if="form.type==='inventory'" class="field"><label for="import-branch">Filial</label><select id="import-branch" v-model="form.branch_id" required><option value="">Selecionar…</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select></div><div class="field"><label for="import-file">Ficheiro CSV ou XLSX · até 10 MB</label><input id="import-file" type="file" accept=".csv,.xlsx" required @change="form.file=$event.target.files[0]"></div></div><p>CSV separado por vírgulas, em UTF-8. Use ponto nas casas decimais. A categoria corresponde ao endereço amigável cadastrado.</p><div class="button-row"><button class="button" :disabled="form.processing">{{form.processing?'A validar…':'Validar ficheiro'}}</button><a :href="'/admin/importacoes/modelo/'+form.type" class="text-link">Descarregar modelo CSV ↓</a></div><progress v-if="form.progress" :value="form.progress.percentage" max="100"/></form><section v-if="batch" class="panel admin-form"><h2>Lote #{{batch.id}} · {{states[batch.status]||batch.status}}</h2><p>{{batch.total_rows}} linhas · {{batch.processed_rows}} importadas · {{batch.failed_rows}} com erros.</p><p v-if="batch.type==='catalog'">Novos produtos entram inativos para revisão antes da publicação.</p><div class="button-row"><button v-if="batch.status==='validated'" class="button" :disabled="confirmation.processing||batch.failed_rows===batch.total_rows" @click="confirmation.post('/admin/importacoes/'+batch.id+'/confirmar')">Importar linhas válidas</button><a :href="'/admin/importacoes/'+batch.id+'/erros'" class="text-link">Descarregar erros ↓</a></div><div class="table-scroll"><table><thead><tr><th>Linha</th><th>SKU</th><th>Estado</th><th>Detalhes</th></tr></thead><tbody><tr v-for="row in batch.import_rows" :key="row.id"><td>{{row.row_number}}</td><td>{{row.payload.sku||'—'}}</td><td>{{states[row.status]||row.status}}</td><td>{{row.error||row.payload.nome||row.payload.stock}}</td></tr></tbody></table></div></section><section class="panel"><div class="table-scroll"><table><thead><tr><th>Lote</th><th>Tipo</th><th>Estado</th><th>Linhas</th><th>Ação</th></tr></thead><tbody><tr v-for="b in batches.data" :key="b.id"><td>#{{b.id}}</td><td>{{b.type==='catalog'?'Produtos':'Stock'}}</td><td>{{states[b.status]||b.status}}</td><td>{{b.total_rows}}</td><td><Link :href="'/admin/importacoes/'+b.id">Abrir ↗</Link></td></tr></tbody></table></div><p v-if="!batches.data.length" class="empty-state">Nenhuma importação.</p><Pagination :links="batches.links"/></section></AdminLayout></template>
